#!/usr/bin/env python3
from __future__ import annotations
import base64, hashlib, secrets, shutil, subprocess
from datetime import datetime
from pathlib import Path

CSS_B64 = ''
JS_B64 = ''
ACCESS_CODE = '14040126'
TITLE = 'برای شما که بخشی از خاطرات من شدید'
MESSAGE = 'رفتن برای من آسون نیست؛ چون بخشی از بهترین خاطرات این مسیر، کنار شما ساخته شد.\nاینجا برای من فقط محل کار نبود؛ پر از خنده\u200cها، روزهای سخت، کمک\u200cکردن\u200cها، شوخی\u200cها و لحظه\u200cهایی بود که همیشه با من می\u200cمونن.\n\nاز اینکه دارم می\u200cرم ناراحتم، اما فکر می\u200cکنم آدم برای رشد و پیشرفت گاهی باید جرأت کنه یک مسیر تازه رو شروع کنه؛ حتی وقتی دل کندن سخت باشه.\n\nهرجا که باشم، به یادتونم و با محبت از این روزها یاد می\u200cکنم. دوستتون دارم و بابت تمام همراهی\u200cها، رفاقت\u200cها، صبوری\u200cها و خاطرات خوبی که با هم ساختیم واقعاً ازتون ممنونم.\n\nامیدوارم مسیر زندگی دوباره ما رو در بهترین شرایط کنار هم قرار بده و باز هم با هم بخندیم.\nمراقب خودتون باشید و همیشه رو به جلو برید.'
SIGNATURE = 'با مهر و کلی خاطره خوب 🤍'
DATE_TEXT = ''

API_IMPORT_START = '# HIDDEN_FAREWELL_IMPORT_START'
API_IMPORT_END = '# HIDDEN_FAREWELL_IMPORT_END'
API_ROUTE_START = '# HIDDEN_FAREWELL_ROUTE_START'
API_ROUTE_END = '# HIDDEN_FAREWELL_ROUTE_END'
INDEX_CSS_START = '<!-- HIDDEN_FAREWELL_CSS_START -->'
INDEX_CSS_END = '<!-- HIDDEN_FAREWELL_CSS_END -->'
INDEX_JS_START = '<!-- HIDDEN_FAREWELL_JS_START -->'
INDEX_JS_END = '<!-- HIDDEN_FAREWELL_JS_END -->'

def replace_marked(text, start, end, block):
    if start in text and end in text:
        return text.split(start, 1)[0] + block + text.split(end, 1)[1]
    return text

def make_secret_py(salt_hex, digest_hex, iterations):
    lines = [
        'from __future__ import annotations', '', 'import hashlib', 'import hmac', '',
        f'_SALT = {salt_hex!r}', f'_EXPECTED = {digest_hex!r}', f'_ITERATIONS = {iterations}', '',
        '_FAREWELL = {', f'    "title": {TITLE!r},', f'    "message": {MESSAGE!r},',
        f'    "signature": {SIGNATURE!r},', f'    "date": {DATE_TEXT!r},', '}', '',
        'def verify_farewell_code(code: str) -> bool:',
        '    candidate = hashlib.pbkdf2_hmac(', '        "sha256",', '        (code or "").encode("utf-8"),',
        '        bytes.fromhex(_SALT),', '        _ITERATIONS,', '    )',
        '    return hmac.compare_digest(candidate, bytes.fromhex(_EXPECTED))', '',
        'def get_farewell_payload() -> dict:', '    return dict(_FAREWELL)', ''
    ]
    return '\n'.join(lines)

def main():
    root = Path.cwd(); frontend = root / 'frontend'; backend = root / 'backend'
    if not frontend.is_dir() or not backend.is_dir(): raise SystemExit('ERROR: فایل را داخل ریشه پروژه اجرا کن؛ پوشه‌های frontend و backend پیدا نشدند.')
    index_path = frontend / 'index.html'; api_path = backend / 'api.py'
    if not index_path.exists() or not api_path.exists(): raise SystemExit('ERROR: index.html یا backend/api.py پیدا نشد.')

    stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    backup = root / f'_backup_hidden_farewell_fixed_{stamp}'; backup.mkdir(parents=True, exist_ok=True)
    for p in [index_path, api_path, frontend/'hidden-farewell.css', frontend/'hidden-farewell.js', backend/'farewell_secret.py']:
        if p.exists(): shutil.copy2(p, backup / p.name)

    salt = secrets.token_bytes(24); iterations = 260000
    digest = hashlib.pbkdf2_hmac('sha256', ACCESS_CODE.encode(), salt, iterations)
    secret_py = make_secret_py(salt.hex(), digest.hex(), iterations)
    (frontend/'hidden-farewell.css').write_bytes(base64.b64decode(CSS_B64))
    (frontend/'hidden-farewell.js').write_bytes(base64.b64decode(JS_B64))
    (backend/'farewell_secret.py').write_text(secret_py, encoding='utf-8', newline='\n')

    index = index_path.read_text(encoding='utf-8')
    css_block = INDEX_CSS_START + '\n    <link rel="stylesheet" href="/static/hidden-farewell.css?v=2">\n    ' + INDEX_CSS_END
    js_block = INDEX_JS_START + '\n    <script src="/static/hidden-farewell.js?v=2"></script>\n    ' + INDEX_JS_END
    if INDEX_CSS_START in index: index = replace_marked(index, INDEX_CSS_START, INDEX_CSS_END, css_block)
    else: index = index.replace('</head>', '    '+css_block+'\n</head>', 1)
    if INDEX_JS_START in index: index = replace_marked(index, INDEX_JS_START, INDEX_JS_END, js_block)
    else: index = index.replace('</body>', '    '+js_block+'\n</body>', 1)
    index_path.write_text(index, encoding='utf-8', newline='\n')

    api = api_path.read_text(encoding='utf-8')
    import_block = API_IMPORT_START + '\nfrom farewell_secret import get_farewell_payload\nfrom farewell_secret import verify_farewell_code\n' + API_IMPORT_END
    if API_IMPORT_START in api: api = replace_marked(api, API_IMPORT_START, API_IMPORT_END, import_block)
    else:
        anchor='from sales_percentage_report import create_sales_percentage_report\n'
        api = api.replace(anchor, anchor+'\n'+import_block+'\n', 1) if anchor in api else import_block+'\n\n'+api

    route_lines = [
        API_ROUTE_START,
        '@app.post("/farewell/unlock")',
        'async def unlock_hidden_farewell(code: str = Form(...)):',
        '    if not verify_farewell_code(code):',
        '        raise HTTPException(status_code=403, detail="Access denied")',
        '    payload = get_farewell_payload()',
        '    return {"ok": True, **payload}',
        API_ROUTE_END,
    ]
    route_block = '\n'.join(route_lines)
    if API_ROUTE_START in api: api = replace_marked(api, API_ROUTE_START, API_ROUTE_END, route_block)
    else:
        marker='@app.get("/health")'; pos=api.find(marker)
        api = api[:pos]+route_block+'\n\n'+api[pos:] if pos >= 0 else api+'\n\n'+route_block+'\n'
    api_path.write_text(api, encoding='utf-8', newline='\n')

    py=subprocess.run(['python','-m','py_compile',str(api_path),str(backend/'farewell_secret.py')],capture_output=True,text=True)
    if py.returncode: raise SystemExit('Python syntax error:\n'+py.stderr)
    try:
        node=subprocess.run(['node','--check',str(frontend/'hidden-farewell.js')],capture_output=True,text=True)
        if node.returncode: raise SystemExit('JavaScript syntax error:\n'+node.stderr)
    except FileNotFoundError: pass
    print('DONE ✅  بخش خداحافظی مخفی نصب شد.')
    print('۵ کلیک روی لوگو → ورود کد → نمایش پیام.')
    print('کد اشتباه → پنجره بسته می‌شود و پیام «دسترسی ندارید» نمایش داده می‌شود.')
    print('Backup:', backup)
    print('منطق گزارش‌ها و دکمه‌ها تغییر نکرد.')

if __name__ == '__main__': main()
